-- c001-v001: Ìran Ọbadáyà: Báyìí– ní–Olúwa Olúwa Jéhófà sí–Édómù ìròyìn a–ti–gbọ́ láti–ọ̀dọ̀ Jéhófà àti–oníṣẹ́ láàárín–àwọn–orílẹ̀–èdè a–rán–lọ: Ẹ–dìde kí–a–sì–dìde sí–i fún–ogun.
-- c001-v002: Wò–o, kékeré mo–ti–sọ–ọ–di láàárín–àwọn–orílẹ̀–èdè; ẹni–a–gàn ìwọ púpọ̀.
-- c001-v003: Ìgbéraga ọkàn–rẹ ti–tàn–ọ́–jẹ, olùgbé–inú àwọn–ìhò– àpáta gíga ibùgbé–rẹ̀; ẹni–tí–ń–sọ nínú–ọkàn–rẹ̀, Ta–ni yóò–sọ–mí–kalẹ̀ sí–ilẹ̀?
-- c001-v004: Bí–o–bá– gbé–ga bí–idì, àti–bí– láàárín àwọn–ìràwọ̀ o–bá–fi ìtẹ́–rẹ; láti–ibẹ̀ èmi–yóò–sọ–ọ́–kalẹ̀ –wí– Jéhófà.
-- c001-v005: Bí– olè bá–wá– sí–ọ bí– ọlọ́sà òru báwo ni–a–ti–pa–ọ́–rẹ́! Ṣé wọ́n–ì–bá–jí tó–wọn? Bí– akórẹ̀–àjàrà bá–wá sí–ọ, ṣé wọ́n–ì–bá–fi–sílẹ̀ àwọn–tí–a–kù?
-- c001-v006: Báwo ni–a–ṣe–wá– Ésáù! A–ti–tú–jáde ohun–tí–ó–pa–mọ́.
-- c001-v007: Títí–dé– ààlà wọ́n–ti–rán–ọ; gbogbo àwọn–ènìyàn májẹ̀mú–rẹ wọ́n–ti–tàn–ọ́–jẹ wọ́n–borí rẹ àwọn–ènìyàn àlàáfíà–rẹ; búrẹ́dì–rẹ wọ́n–fi ìdẹ́kùn sí–abẹ́–rẹ; kò–sí òye nínú–rẹ̀.
-- c001-v008: Ṣé ní–ọjọ́ náà –wí– Jéhófà èmi–yóò–pa–run àwọn–ọlọ́gbọ́n láti–Édómù, àti–òye láti–òkè Ésáù?
-- c001-v009: Àti–àwọn–akọni–rẹ akọni–rẹ Témánì yóò–bẹ̀rù, kí– ọkùnrin–kọ̀ọ̀kan kí–ó–le–ké–kúrò– láti–òkè Ésáù
-- c001-v010: Nítorí–ìwà–ipá sí–arákùnrin–rẹ Jékọ́bù ìtìjú–yóò–bo–ọ́, ìtìjú, a–ó–sì–ké–ọ–kúrò títí–láé.
-- c001-v011: Ní–ọjọ́ tí–o–dúró ní–òdìkejì, ní–ọjọ́ tí–àwọn–àjèjì–mú àwọn–àjèjì ohun–ìní–rẹ̀; àti–àwọn–àjòjì wọ́n–wọlé [ẹnu–ọ̀nà–rẹ̀] (ẹnu–ọ̀nà–rẹ̀) àti–lé– Jerúsálẹ́mù wọ́n–sọ kèké; àní– ìwọ gẹ́gẹ́–bí–ọ̀kan nínú–wọn.
-- c001-v012: Àti–má–ṣe– wo ní–ọjọ́– arákùnrin–rẹ ní–ọjọ́ àjèjì–rẹ̀, àti–má–ṣe– yọ̀ lórí–àwọn– Júdà ní–ọjọ́ ìparun–wọn; àti–má–ṣe– sọ–ọ̀rọ̀–ńlá ẹnu–rẹ ní–ọjọ́ ìpọ́njú.
-- c001-v013: Má–ṣe– wọ–inú ẹnu–ọ̀nà– àwọn–ènìyàn–mi ní–ọjọ́ ìṣubú–wọn, má–ṣe– wo àní– ìwọ ìṣubú–rẹ̀ ní–ọjọ́ ìṣubú–rẹ̀; àti–má–ṣe– na–ọwọ́–sí ohun–ìní–rẹ̀ ní–ọjọ́ ìṣubú–rẹ̀.
-- c001-v014: Àti–má–ṣe– dúró lé– ìkojá, láti–ké–kúrò àwọn asálà–rẹ̀; àti–má–ṣe– fi–lé–ọwọ́ àwọn–tí–ó–kù–rẹ̀ ní–ọjọ́ ìpọ́njú.
-- c001-v015: Nítorí– ó–súnmọ́ ọjọ́– Jéhófà lé– gbogbo– àwọn–orílẹ̀–èdè; gẹ́gẹ́–bí o–ti–ṣe a–ó–ṣe sí–ọ, ìgbẹ̀san–rẹ yóò–padà sí–orí–rẹ.
-- c001-v016: Nítorí gẹ́gẹ́–bí ẹ̀yin–ti–mu lé– òkè mímọ́–mi, gbogbo–àwọn–orílẹ̀–èdè–yóò–mu gbogbo– àwọn–orílẹ̀–èdè títí–láé; wọ́n–ó–sì–mu àti–gbe–mì, wọ́n–ó–sì–dà–bí bí–ẹni–tí–kò wà.
-- c001-v017: Àti–lórí–òkè Síónì àsálà–yóò–wà àsálà yóò–sì–wà mímọ́; ilé–Jékọ́bù–yóò–sì–jogún ilé Jékọ́bù ohun–ìní wọn.
-- c001-v018: Ilé–yóò–sì–di ilé– Jékọ́bù iná àti–ilé Jósẹ́fù ọ̀wọ́–iná, àti–ilé Ésáù koríko–gbígbẹ, wọ́n–ó–sì–jó–wọn sínú–wọn wọ́n–ó–sì–jẹ–wọ́n–run; kì–yóò–sì– sí ẹni–asálà fún–ilé Ésáù; nítorí Jéhófà ti–sọ.
-- c001-v019: Àwọn–tí–ó–wà–ní–Gúúsù–yóò–jogún Gúúsù ohun–ìní– òkè Ésáù, àti–àwọn–pẹ̀tẹ́lẹ̀ ohun–ìní– àwọn–Fílístínì; wọ́n–ó–sì–jogún ohun–ìní– pápá Éfúráímù, àti– pápá Samáríà; àti–Bẹ́njámínì ohun–ìní– Gílíádì.
-- c001-v020: Àti–àwọn–ìgbèkùn ti–ogun– yìí ti–àwọn–ọmọ Ísírẹ́lì àwọn–tí– àwọn–Kénáánì títí–dé– Sárẹ́fátì, àti–àwọn–ìgbèkùn Jerúsálẹ́mù àwọn–tí–ó–wà ní–Sẹ́fárádì yóò–jogún ohun–ìní àwọn–ìlú Gúúsù.
-- c001-v021: Àwọn–olùgbàlà–yóò–sì–gòkè àwọn–olùgbàlà lé–òkè Síónì, láti–ṣe–ìdájọ́ ohun–ìní– òkè Ésáù; ìjọba–yóò–sì–jẹ́ ti–Jéhófà ìjọba.

